                 //         "rateLimits": [],
                 //         "exchangeFilters": [],
                 //         "symbols": [
                 //           {
                 //                "symbol": "OGNUSDT",
                 //                "status": "1",
                 //                "baseAsset": "OGN",
                 //                "baseAssetPrecision": "2",
                 //                "quoteAsset": "USDT",
