  /**
   * @method
   * @name mexc#createOrder
   * @description create a trade order
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/new-order //
   * spot
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/place-order
   * // swap
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/place-plan-order
   * // swap trigger
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] only 'isolated' is supported for
   * spot-margin trading
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {bool} [params.postOnly] if true, the order will only be posted if
   * it will be a maker order
   * @param {bool} [params.reduceOnly] *contract only* indicates if this order
   * is to reduce the size of a position
   * @param {bool} [params.hedged] *swap only* true for hedged mode, false for
   * one way mode, default is false
   * @param {string} [params.timeInForce] 'IOC' or 'FOK', default is 'GTC'
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {int} [params.leverage] *contract only* leverage is necessary on
   * isolated margin
   * @param {long} [params.positionId] *contract only* it is recommended to fill
   * in this parameter when closing a position
   * @param {string} [params.externalOid] *contract only* external order ID
   * @param {int} [params.positionMode] *contract only*  1:hedge, 2:one-way,
   * default: the user's current config
   * @param {boolean} [params.test] *spot only* whether to use the test endpoint
   * or not, default is false
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any marginModequeryVariable =
                     this->handleMarginModeAndParams(std::string("createOrder"),
                                                     params);
                 ccxt::any marginMode = ::getValue(marginModequeryVariable, 0);
                 ccxt::any query = ::getValue(marginModequeryVariable, 1);
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   return awaitValue(this->createSpotOrder(
                       market, type, side, amount, price, marginMode, query));
                 } else {
                   return awaitValue(this->createSwapOrder(
                       market, type, side, amount, price, marginMode, query));
                 }
                 return ccxt::any{};
               })
        .share();
  }

  virtual ccxt::any createSpotOrderRequest(ccxt::any market, ccxt::any type,
                                           ccxt::any side, ccxt::any amount,
                                           ccxt::any price = ccxt::any{},
                                           ccxt::any marginMode = ccxt::any{},
                                           ccxt::any params = ccxt::dict{}) {
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any orderSide = toUpperCase(side);
    ccxt::any request = ccxt::dict{
        {std::string("symbol"), ::getValue(market, std::string("id"))},
        {std::string("side"), orderSide},
        {std::string("type"), toUpperCase(type)},
    };
    if (isTrue(isEqual(type, std::string("market")))) {
      ccxt::any cost = this->safeNumber2(params, std::string("cost"),
                                         std::string("quoteOrderQty"));
      params = this->omit(params, std::string("cost"));
      if (isTrue(!isEqual(cost, ccxt::any{}))) {
        amount = cost;
        ::setValue(request, std::string("quoteOrderQty"),
                   this->costToPrecision(symbol, amount));
      } else {
        if (isTrue(isEqual(price, ccxt::any{}))) {
          ::setValue(request, std::string("quantity"),
                     this->amountToPrecision(symbol, amount));
        } else {
          ccxt::any amountString = this->numberToString(amount);
          ccxt::any priceString = this->numberToString(price);
          ccxt::any quoteAmount =
              ccxt::Precise::stringMul(amountString, priceString);
          amount = quoteAmount;
          ::setValue(request, std::string("quoteOrderQty"),
                     this->costToPrecision(symbol, amount));
        }
      }
    } else {
      ::setValue(request, std::string("quantity"),
                 this->amountToPrecision(symbol, amount));
    }
    if (isTrue(!isEqual(price, ccxt::any{}))) {
      ::setValue(request, std::string("price"),
                 this->priceToPrecision(symbol, price));
    }
    ccxt::any clientOrderId =
        this->safeString(params, std::string("clientOrderId"));
    if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
      ::setValue(request, std::string("newClientOrderId"), clientOrderId);
      params = this->omit(params, ccxt::list{std::string("type"),
                                             std::string("clientOrderId")});
    }
    if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
      if (isTrue(!isEqual(marginMode, std::string("isolated")))) {
        throw BadRequest(toString(add(
            add(add(this->id,
                    std::string(" createOrder() does not support marginMode ")),
                marginMode),
            std::string(" for spot-margin trading"))));
      }
    }
    ccxt::any postOnly = ccxt::any{};
    ccxt::any postOnlyparamsVariable =
        this->handlePostOnly(isEqual(type, std::string("market")),
                             isEqual(type, std::string("LIMIT_MAKER")), params);
    postOnly = ::getValue(postOnlyparamsVariable, 0);
    params = ::getValue(postOnlyparamsVariable, 1);
    if (isTrue(isEqual(postOnly, true))) {
      ::setValue(request, std::string("type"), std::string("LIMIT_MAKER"));
    }
    ccxt::any tif = this->safeString(params, std::string("timeInForce"));
    if (isTrue(!isEqual(tif, ccxt::any{}))) {
      params = this->omit(params, std::string("timeInForce"));
      if (isTrue(isEqual(tif, std::string("IOC")))) {
        ::setValue(request, std::string("type"),
                   std::string("IMMEDIATE_OR_CANCEL"));
      } else if (isTrue(isEqual(tif, std::string("FOK")))) {
        ::setValue(request, std::string("type"), std::string("FILL_OR_KILL"));
      }
    }
    return this->extend(request, params);
  }

  /**
   * @ignore
   * @method
   * @name mexc#createSpotOrder
   * @description create a trade order
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/new-order
   * @param {string} market unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {string} [marginMode] only 'isolated' is supported for spot-margin
   * trading
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.postOnly] if true, the order will only be posted if
   * it will be a maker order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  createSpotOrder(ccxt::any market, ccxt::any type, ccxt::any side,
                  ccxt::any amount, ccxt::any price = ccxt::any{},
                  ccxt::any marginMode = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any test =
                     this->safeBool(params, std::string("test"), false);
                 params = this->omit(params, std::string("test"));
                 ccxt::any request = this->createSpotOrderRequest(
                     market, type, side, amount, price, marginMode, params);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(test, true))) {
                   response =
                       awaitValue(this->spotPrivatePostOrderTest(request));
                 } else {
                   response = awaitValue(this->spotPrivatePostOrder(request));
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "symbol": "BTCUSDT",
                 //         "orderId": "123738410679123456",
                 //         "orderListId": -1
                 //     }
                 //
                 // margin
                 //
                 //     {
                 //         "symbol": "BTCUSDT",
                 //         "orderId": "762634301354414080",
                 //         "clientOrderId": null,
                 //         "isIsolated": true,
                 //         "transactTime": 1661992652132
                 //     }
                 //
                 ccxt::any order = this->parseOrder(response, market);
                 ::setValue(order, std::string("side"), side);
                 ::setValue(order, std::string("type"), type);
                 if (isTrue(
                         isEqual(this->safeString(order, std::string("price")),
                                 ccxt::any{}))) {
                   ::setValue(order, std::string("price"), price);
                 }
                 if (isTrue(
                         isEqual(this->safeString(order, std::string("amount")),
                                 ccxt::any{}))) {
                   ::setValue(order, std::string("amount"), amount);
                 }
                 return order;
               })
        .share();
  }

  /**
   * @ignore
   * @method
   * @name mexc#createSwapOrder
   * @description create a trade order
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/place-order
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/place-plan-order
   * @param {string} market unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {string} [marginMode] only 'isolated' is supported for spot-margin
   * trading
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {bool} [params.postOnly] if true, the order will only be posted if
   * it will be a maker order
   * @param {bool} [params.reduceOnly] indicates if this order is to reduce the
   * size of a position
   * @param {bool} [params.hedged] *swap only* true for hedged mode, false for
   * one way mode, default is false
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {int} [params.leverage] leverage is necessary on isolated margin
   * @param {long} [params.positionId] it is recommended to fill in this
   * parameter when closing a position
   * @param {string} [params.externalOid] external order ID
   * @param {int} [params.positionMode] 1:hedge, 2:one-way, default: the user's
   * current config
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  createSwapOrder(ccxt::any market, ccxt::any type, ccxt::any side,
                  ccxt::any amount, ccxt::any price = ccxt::any{},
                  ccxt::any marginMode = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any symbol = ::getValue(market, std::string("symbol"));
                 ccxt::any openType = ccxt::any{};
                 if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                   if (isTrue(isEqual(marginMode, std::string("cross")))) {
                     openType = 2;
                   } else if (isTrue(isEqual(marginMode,
                                             std::string("isolated")))) {
                     openType = 1;
                   } else {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(
                             " createSwapOrder() marginMode parameter should "
                             "be either \"cross\" or \"isolated\""))));
                   }
                 } else {
                   openType =
                       this->safeInteger(params, std::string("openType"),
                                         2); // defaulting to cross margin
                 }
                 if (isTrue(
                         isTrue(
                             isTrue(
                                 isTrue(
                                     isTrue(
                                         isTrue(
                                             isTrue(
                                                 isTrue((!isEqual(
                                                     type,
                                                     std::string("limit")))) &&
                                                 isTrue((!isEqual(
                                                     type, std::string(
                                                               "market"))))) &&
                                             isTrue((!isEqual(type, 1)))) &&
                                         isTrue((!isEqual(type, 2)))) &&
                                     isTrue((!isEqual(type, 3)))) &&
                                 isTrue((!isEqual(type, 4)))) &&
                             isTrue((!isEqual(type, 5)))) &&
                         isTrue((!isEqual(type, 6))))) {
                   throw InvalidOrder(toString(
                       add(this->id,
                           std::string(
                               " createSwapOrder() order type must either "
                               "limit, market, or 1 for limit orders, 2 for "
                               "post-only orders, 3 for IOC orders, 4 for FOK "
                               "orders, 5 for market orders or 6 to convert "
                               "market price to current price"))));
                 }
                 ccxt::any postOnly = ccxt::any{};
                 ccxt::any postOnlyparamsVariable =
                     this->handlePostOnly(isEqual(type, std::string("market")),
                                          isEqual(type, 2), params);
                 postOnly = ::getValue(postOnlyparamsVariable, 0);
                 params = ::getValue(postOnlyparamsVariable, 1);
                 if (isTrue(isEqual(postOnly, true))) {
                   type = 2;
                 } else if (isTrue(isEqual(type, std::string("limit")))) {
                   type = 1;
                 } else if (isTrue(isEqual(type, std::string("market")))) {
                   type = 6;
                 }
                 ccxt::any volString = this->amountToPrecision(symbol, amount);
                 if (isTrue(isEqual(volString, ccxt::any{}))) {
                   volString = std::string("0");
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("vol"), parseFloat(volString)},
                     {std::string("type"), type},
                     {std::string("openType"), openType},
                 };
                 if (isTrue(isTrue(isTrue((!isEqual(type, 5))) &&
                                   isTrue((!isEqual(type, 6)))) &&
                            isTrue((!isEqual(type, std::string("market")))))) {
                   ccxt::any priceString =
                       this->priceToPrecision(symbol, price);
                   if (isTrue(isEqual(priceString, ccxt::any{}))) {
                     priceString = std::string("0");
                   }
                   ::setValue(request, std::string("price"),
                              parseFloat(priceString));
                 }
                 if (isTrue(isEqual(openType, 1))) {
                   ccxt::any leverage =
                       this->safeInteger(params, std::string("leverage"));
                   if (isTrue(isEqual(leverage, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" createSwapOrder() requires a leverage "
                                     "parameter for isolated margin orders"))));
                   }
                 }
                 ccxt::any reduceOnly =
                     this->safeBool(params, std::string("reduceOnly"), false);
                 ccxt::any hedged =
                     this->safeBool(params, std::string("hedged"), false);
                 ccxt::any sideInteger = ccxt::any{};
                 if (isTrue(isEqual(hedged, true))) {
                   if (isTrue(isEqual(reduceOnly, true))) {
                     params = this->omit(
                         params,
                         std::string("reduceOnly")); // hedged mode does not
                                                     // accept this parameter
                     sideInteger =
                         (isTrue((isEqual(side, std::string("buy"))))
                              ? ccxt::any(4)
                              : ccxt::any(2)); // close short, close long
                   } else {
                     sideInteger = (isTrue((isEqual(side, std::string("buy"))))
                                        ? ccxt::any(1)
                                        : ccxt::any(3));
                   }
                   ::setValue(request, std::string("positionMode"), 1);
                 } else {
                   if (isTrue(isEqual(reduceOnly, true))) {
                     sideInteger = (isTrue((isEqual(side, std::string("buy"))))
                                        ? ccxt::any(2)
                                        : ccxt::any(4));
                     params = this->omit(params, std::string("reduceOnly"));
                   } else {
                     sideInteger = (isTrue((isEqual(side, std::string("buy"))))
                                        ? ccxt::any(1)
                                        : ccxt::any(3));
                   }
                 }
                 ::setValue(request, std::string("side"), sideInteger);
                 ccxt::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("externalOid"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("externalOid"),
                              clientOrderId);
                 }
                 ccxt::any triggerPrice =
                     this->safeNumber2(params, std::string("triggerPrice"),
                                       std::string("stopPrice"));
                 params =
                     this->omit(params, ccxt::list{std::string("clientOrderId"),
                                                   std::string("externalOid"),
                                                   std::string("postOnly"),
                                                   std::string("stopPrice"),
                                                   std::string("triggerPrice"),
                                                   std::string("hedged")});
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isTrue((!isEqual(triggerPrice, ccxt::any{}))) &&
                            isTrue((!isEqual(triggerPrice, 0))))) {
                   ::setValue(request, std::string("triggerPrice"),
                              this->priceToPrecision(symbol, triggerPrice));
                   ::setValue(request, std::string("triggerType"),
                              this->safeInteger(params,
                                                std::string("triggerType"), 1));
                   ::setValue(request, std::string("executeCycle"),
                              this->safeInteger(
                                  params, std::string("executeCycle"), 1));
                   ::setValue(
                       request, std::string("trend"),
                       this->safeInteger(params, std::string("trend"), 1));
                   ::setValue(
                       request, std::string("orderType"),
                       this->safeInteger(params, std::string("orderType"), 1));
                   response =
                       awaitValue(this->contractPrivatePostPlanorderPlace(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->contractPrivatePostOrderCreate(
                       this->extend(request, params)));
                 }
                 //
                 // Swap
                 //     {"code":200,"data":"2ff3163e8617443cb9c6fc19d42b1ca4"}
                 //
                 // Trigger
                 //     {"success":true,"code":0,"data":259208506303929856}
                 //
                 // {"success":true,"code":0,"data":{"orderId":"814218083416790528","ts":1779795118533}}
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"));
                 return this->safeOrder(
                     ccxt::dict{
                         {std::string("id"),
                          this->safeString(data, std::string("orderId"))},
                         {std::string("timestamp"),
                          this->safeInteger(data, std::string("ts"))},
                     },
                     market);
               })
        .share();
  }

  /**
   * @method
   * @name mexc#createOrders
   * @description *spot only*  *all orders must have the same symbol* create a
   * list of trade orders
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/batch-orders
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params] extra parameters specific to api endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrders(ccxt::any orders, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any ordersRequests = ccxt::list{};
                 ccxt::any symbol = ccxt::any{};
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   ccxt::any rawOrder = ::getValue(orders, i);
                   ccxt::any marketId =
                       this->safeString(rawOrder, std::string("symbol"));
                   ccxt::any market = this->market(marketId);
                   if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                       true))) {
                     throw NotSupported(toString(add(
                         this->id, std::string(" createOrders() is only "
                                               "supported for spot markets"))));
                   }
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     symbol = marketId;
                   } else {
                     if (isTrue(!isEqual(symbol, marketId))) {
                       throw BadRequest(toString(
                           add(this->id,
                               std::string(" createOrders() requires all "
                                           "orders to have the same symbol"))));
                     }
                   }
                   ccxt::any type =
                       this->safeString(rawOrder, std::string("type"));
                   ccxt::any side =
                       this->safeString(rawOrder, std::string("side"));
                   ccxt::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   ccxt::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   ccxt::any orderParams = this->safeValue(
                       rawOrder, std::string("params"), ccxt::dict{});
                   ccxt::any marginMode = ccxt::any{};
                   ccxt::any marginModeparamsVariable =
                       this->handleMarginModeAndParams(
                           std::string("createOrder"), params);
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   ccxt::any orderRequest = this->createSpotOrderRequest(
                       market, type, side, amount, price, marginMode,
                       orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("batchOrders"), this->json(ordersRequests)},
                 };
                 ccxt::any response =
                     awaitValue(this->spotPrivatePostBatchOrders(request));
                 //
                 // [
                 //     {
                 //       "symbol": "BTCUSDT",
                 //       "orderId": "1196315350023612316",
                 //       "newClientOrderId": "hio8279hbdsds",
                 //       "orderListId": -1
                 //     },
                 //     {
                 //       "newClientOrderId": "123456",
                 //       "msg": "The minimum transaction volume cannot be less
                 //       than:0.5USDT", "code": 30002
                 //     },
                 //     {
                 //       "symbol": "BTCUSDT",
                 //       "orderId": "1196315350023612318",
                 //       "orderListId": -1
                 //     }
                 // ]
                 //
                 return this->parseOrders(response);
               })
        .share();
  }

  /**
   * @method
   * @name mexc#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/query-order
   * // spot
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-order-information-by-order-id
   * // swap
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] only 'isolated' is supported, for
   * spot-margin trading
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " fetchOrder() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any data = ccxt::dict{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   ccxt::any clientOrderId =
                       this->safeString(params, std::string("clientOrderId"));
                   if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                     params = this->omit(params, std::string("clientOrderId"));
                     ::setValue(request, std::string("origClientOrderId"),
                                clientOrderId);
                   } else {
                     ::setValue(request, std::string("orderId"), id);
                   }
                   ccxt::any marginModequeryVariable =
                       this->handleMarginModeAndParams(
                           std::string("fetchOrder"), params);
                   ccxt::any marginMode =
                       ::getValue(marginModequeryVariable, 0);
                   ccxt::any query = ::getValue(marginModequeryVariable, 1);
                   if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                     if (isTrue(
                             !isEqual(marginMode, std::string("isolated")))) {
                       throw BadRequest(toString(
                           add(add(add(this->id,
                                       std::string(" fetchOrder() does not "
                                                   "support marginMode ")),
                                   marginMode),
                               std::string(" for spot-margin trading"))));
                     }
                     data = awaitValue(this->spotPrivateGetMarginOrder(
                         this->extend(request, query)));
                   } else {
                     data = awaitValue(this->spotPrivateGetOrder(
                         this->extend(request, query)));
                   }
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("swap")),
                                        true))) {
                   ::setValue(request, std::string("order_id"), id);
                   ccxt::any response =
                       awaitValue(this->contractPrivateGetOrderGetOrderId(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "success": true,
                   //         "code": "0",
                   //         "data": {
                   //             "orderId": "264995729269765120",
                   //             "symbol": "STEPN_USDT",
                   //             "positionId": "0",
                   //             "price": "2.2",
                   //             "vol": "15",
                   //             "leverage": "20",
                   //             "side": "1",
                   //             "category": "1",
                   //             "orderType": "1",
                   //             "dealAvgPrice": "0",
                   //             "dealVol": "0",
                   //             "orderMargin": "2.2528",
                   //             "takerFee": "0",
                   //             "makerFee": "0",
                   //             "profit": "0",
                   //             "feeCurrency": "USDT",
                   //             "openType": "1",
                   //             "state": "2",
                   //             "externalOid":
                   //             "_m_0e9520c256744d64b942985189026d20",
                   //             "errorCode": "0",
                   //             "usedMargin": "0",
                   //             "createTime": "1648850305236",
                   //             "updateTime": "1648850305245",
                   //             "positionMode": "1"
                   //         }
                   //     }
                   //
                   data = this->safeValue(response, std::string("data"));
                 }
                 return this->parseOrder(data, market);
               })
        .share();
  }

  /**
   * @method
   * @name mexc#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/all-orders //
   * spot
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-all-historical-orders
   * // swap
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-plan-order-list
   * // swap trigger
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch orders for
   * @param {string} [params.marginMode] only 'isolated' is supported, for
   * spot-margin trading
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any until =
                     this->safeInteger(params, std::string("until"));
                 params = this->omit(params, std::string("until"));
                 ccxt::any marketTypequeryVariable =
                     this->handleMarketTypeAndParams(std::string("fetchOrders"),
                                                     market, params);
                 ccxt::any marketType = ::getValue(marketTypequeryVariable, 0);
                 ccxt::any query = ::getValue(marketTypequeryVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(" fetchOrders() requires a symbol "
                                         "argument for spot market"))));
                   }
                   ccxt::any marginModequeryInnerVariable =
                       this->handleMarginModeAndParams(
                           std::string("fetchOrders"), params);
                   ccxt::any marginMode =
                       ::getValue(marginModequeryInnerVariable, 0);
                   ccxt::any queryInner =
                       ::getValue(marginModequeryInnerVariable, 1);
                   if (isTrue(!isEqual(since, ccxt::any{}))) {
                     ::setValue(request, std::string("startTime"), since);
                   }
                   if (isTrue(!isEqual(until, ccxt::any{}))) {
                     ::setValue(request, std::string("endTime"), until);
                   }
                   if (isTrue(!isEqual(limit, ccxt::any{}))) {
                     ::setValue(request, std::string("limit"), limit);
                   }
                   ccxt::any response = ccxt::any{};
                   if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                     if (isTrue(
                             !isEqual(marginMode, std::string("isolated")))) {
                       throw BadRequest(toString(
                           add(add(add(this->id,
                                       std::string(" fetchOrders() does not "
                                                   "support marginMode ")),
                                   marginMode),
                               std::string(" for spot-margin trading"))));
                     }
                     response = awaitValue(this->spotPrivateGetMarginAllOrders(
                         this->extend(request, queryInner)));
                   } else {
                     response = awaitValue(this->spotPrivateGetAllOrders(
                         this->extend(request, queryInner)));
                   }
                   //
                   // spot
                   //
                   //     [
                   //         {
                   //             "symbol": "BTCUSDT",
                   //             "orderId": "133949373632483328",
                   //             "orderListId": "-1",
                   //             "clientOrderId": null,
                   //             "price": "45000",
                   //             "origQty": "0.0002",
                   //             "executedQty": "0",
                   //             "cummulativeQuoteQty": "0",
                   //             "status": "NEW",
                   //             "timeInForce": null,
                   //             "type": "LIMIT",
                   //             "side": "SELL",
                   //             "stopPrice": null,
                   //             "icebergQty": null,
                   //             "time": "1647718255000",
                   //             "updateTime": "1647718255000",
                   //             "isWorking": true,
                   //             "origQuoteOrderQty": "9"
                   //         },
                   //     ]
                   //
                   // margin
                   //
                   //     [
                   //         {
                   //             "symbol": "BTCUSDT",
                   //             "orderId": "763307297891028992",
                   //             "orderListId": "-1",
                   //             "clientOrderId": null,
                   //             "price": "18000",
                   //             "origQty": "0.0014",
                   //             "executedQty": "0",
                   //             "cummulativeQuoteQty": "0",
                   //             "status": "NEW",
                   //             "type": "LIMIT",
                   //             "side": "BUY",
                   //             "isIsolated": true,
                   //             "isWorking": true,
                   //             "time": 1662153107000,
                   //             "updateTime": 1662153107000
                   //         }
                   //     ]
                   //
                   return this->parseOrders(response, market, since, limit);
                 } else {
                   if (isTrue(!isEqual(since, ccxt::any{}))) {
                     ::setValue(request, std::string("start_time"), since);
                     ccxt::any end = this->safeInteger(
                         params, std::string("end_time"), until);
                     if (isTrue(isEqual(end, ccxt::any{}))) {
                       ::setValue(
                           request, std::string("end_time"),
                           this->sum(since, ::getValue(this->options,
                                                       std::string(
                                                           "maxTimeTillEnd"))));
                     } else {
                       if (isTrue(isGreaterThan(
                               (subtract(end, since)),
                               ::getValue(this->options,
                                          std::string("maxTimeTillEnd"))))) {
                         throw BadRequest(toString(
                             add(this->id,
                                 std::string(" end is invalid, i.e. exceeds "
                                             "allowed 90 days."))));
                       } else {
                         ::setValue(request, std::string("end_time"), until);
                       }
                     }
                   } else if (isTrue(!isEqual(until, ccxt::any{}))) {
                     ::setValue(
                         request, std::string("start_time"),
                         this->sum(
                             until,
                             multiply(::getValue(this->options,
                                                 std::string("maxTimeTillEnd")),
                                      -1)));
                     ::setValue(request, std::string("end_time"), until);
                   }
                   if (isTrue(!isEqual(limit, ccxt::any{}))) {
                     ::setValue(request, std::string("page_size"), limit);
                   }
                   ccxt::any method = this->safeString(
                       this->options, std::string("fetchOrders"),
                       std::string("contractPrivateGetOrderListHistoryOrders"));
                   method =
                       this->safeString(query, std::string("method"), method);
                   ccxt::any ordersOfRegular = ccxt::list{};
                   ccxt::any ordersOfTrigger = ccxt::list{};
                   if (isTrue(isEqual(
                           method,
                           std::string(
                               "contractPrivateGetOrderListHistoryOrders")))) {
                     ccxt::any response = awaitValue(
                         this->contractPrivateGetOrderListHistoryOrders(
                             this->extend(request, query)));
                     //
                     //     {
                     //         "success": true,
                     //         "code": "0",
                     //         "data": [
                     //             {
                     //                 "orderId": "265230764677709315",
                     //                 "symbol": "STEPN_USDT",
                     //                 "positionId": "0",
                     //                 "price": "2.1",
                     //                 "vol": "102",
                     //                 "leverage": "20",
                     //                 "side": "1",
                     //                 "category": "1",
                     //                 "orderType": "1",
                     //                 "dealAvgPrice": "0",
                     //                 "dealVol": "0",
                     //                 "orderMargin": "10.96704",
                     //                 "takerFee": "0",
                     //                 "makerFee": "0",
                     //                 "profit": "0",
                     //                 "feeCurrency": "USDT",
                     //                 "openType": "1",
                     //                 "state": "2",
                     //                 "externalOid":
                     //                 "_m_7e42f8df6b324c869e4e200397e2b00f",
                     //                 "errorCode": "0",
                     //                 "usedMargin": "0",
                     //                 "createTime": "1648906342000",
                     //                 "updateTime": "1648906342000",
                     //                 "positionMode": "1"
                     //             },
                     //          ]
                     //     }
                     //
                     ordersOfRegular =
                         this->safeValue(response, std::string("data"));
                   } else {
                     // the Planorder endpoints work not only for stop-market
                     // orders, but also for stop-limit orders that were
                     // supposed to have a separate endpoint
                     ccxt::any response =
                         awaitValue(this->contractPrivateGetPlanorderListOrders(
                             this->extend(request, query)));
                     //
                     //     {
                     //         "success": true,
                     //         "code": "0",
                     //         "data": [
                     //             {
                     //                 "symbol": "STEPN_USDT",
                     //                 "leverage": "20",
                     //                 "side": "1",
                     //                 "vol": "13",
                     //                 "openType": "1",
                     //                 "state": "1",
                     //                 "orderType": "1",
                     //                 "errorCode": "0",
                     //                 "createTime": "1648984276000",
                     //                 "updateTime": "1648984276000",
                     //                 "id": "265557643326564352",
                     //                 "triggerType": "1",
                     //                 "triggerPrice": "3",
                     //                 "price": "2.9", // not present in
                     //                 stop-market, but in stop-limit order
                     //                 "executeCycle": "87600",
                     //                 "trend": "1",
                     //             },
                     //         ]
                     //     }
                     //
                     ordersOfTrigger =
                         this->safeValue(response, std::string("data"));
                   }
                   ccxt::any merged =
                       this->arrayConcat(ordersOfTrigger, ordersOfRegular);
                   return this->parseOrders(merged, market, since, limit,
                                            params);
                 }
                 return ccxt::any{};
               })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  fetchOrdersByIds(ccxt::any ids, ccxt::any symbol = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any marketTypequeryVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOrdersByIds"), market, params);
                 ccxt::any marketType = ::getValue(marketTypequeryVariable, 0);
                 ccxt::any query = ::getValue(marketTypequeryVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   throw BadRequest(toString(add(
                       add(this->id,
                           std::string(
                               " fetchOrdersByIds() is not supported for ")),
                       marketType)));
                 } else {
                   ::setValue(request, std::string("order_ids"),
                              join(ids, std::string(",")));
                   ccxt::any response =
                       awaitValue(this->contractPrivateGetOrderBatchQuery(
                           this->extend(request, query)));
                   //
                   //     {
                   //         "success": true,
                   //         "code": "0",
                   //         "data": [
                   //             {
                   //                 "orderId": "265230764677709315",
                   //                 "symbol": "STEPN_USDT",
                   //                 "positionId": "0",
                   //                 "price": "2.1",
                   //                 "vol": "102",
                   //                 "leverage": "20",
                   //                 "side": "1",
                   //                 "category": "1",
                   //                 "orderType": "1",
                   //                 "dealAvgPrice": "0",
                   //                 "dealVol": "0",
                   //                 "orderMargin": "10.96704",
                   //                 "takerFee": "0",
                   //                 "makerFee": "0",
                   //                 "profit": "0",
                   //                 "feeCurrency": "USDT",
                   //                 "openType": "1",
                   //                 "state": "2",
                   //                 "externalOid":
                   //                 "_m_7e42f8df6b324c869e4e200397e2b00f",
                   //                 "errorCode": "0",
                   //                 "usedMargin": "0",
                   //                 "createTime": "1648906342000",
                   //                 "updateTime": "1648906342000",
                   //                 "positionMode": "1"
                   //             }
                   //         ]
                   //     }
                   //
                   ccxt::any data =
                       this->safeList(response, std::string("data"));
                   return this->parseOrders(data, market);
                 }
                 return ccxt::any{};
               })
        .share();
  }

  /**
   * @method
   * @name mexc#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://www.mexc.com/api-docs/spot-v3/spot-account-trade/current-open-orders
   * // spot
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-current-orders
   * // swap
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-plan-order-list
   * // swap trigger
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] only 'isolated' is supported, for
   * spot-margin trading
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 ccxt::any marketType = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOpenOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                this->safeString(market, std::string("id")));
                   }
                   ccxt::any marginModequeryVariable =
                       this->handleMarginModeAndParams(
                           std::string("fetchOpenOrders"), params);
                   ccxt::any marginMode =
                       ::getValue(marginModequeryVariable, 0);
                   ccxt::any query = ::getValue(marginModequeryVariable, 1);
                   ccxt::any response = ccxt::any{};
                   if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                     if (isTrue(
                             !isEqual(marginMode, std::string("isolated")))) {
                       throw BadRequest(toString(
                           add(add(add(this->id,
                                       std::string(" fetchOpenOrders() does "
                                                   "not support marginMode ")),
                                   marginMode),
                               std::string(" for spot-margin trading"))));
                     }
                     response = awaitValue(this->spotPrivateGetMarginOpenOrders(
                         this->extend(request, query)));
                   } else {
                     response = awaitValue(this->spotPrivateGetOpenOrders(
                         this->extend(request, query)));
                   }
                   //
                   // spot
                   //
                   //     [
                   //         {
                   //             "symbol": "BTCUSDT",
                   //             "orderId": "133949373632483328",
                   //             "orderListId": "-1",
                   //             "clientOrderId": "",
                   //             "price": "45000",
                   //             "origQty": "0.0002",
                   //             "executedQty": "0",
                   //             "cummulativeQuoteQty": "0",
                   //             "status": "NEW",
                   //             "timeInForce": null,
                   //             "type": "LIMIT",
                   //             "side": "SELL",
                   //             "stopPrice": null,
                   //             "icebergQty": null,
                   //             "time": "1647718255199",
                   //             "updateTime": null,
                   //             "isWorking": true,
                   //             "origQuoteOrderQty": "9"
                   //         }
                   //     ]
                   //
                   // margin
                   //
                   //     [
                   //         {
                   //             "symbol": "BTCUSDT",
                   //             "orderId": "764547676405633024",
                   //             "orderListId": "-1",
                   //             "clientOrderId": null,
                   //             "price": "18000",
                   //             "origQty": "0.0013",
                   //             "executedQty": "0",
                   //             "cummulativeQuoteQty": "0",
                   //             "status": "NEW",
                   //             "type": "LIMIT",
                   //             "side": "BUY",
                   //             "isIsolated": true,
                   //             "isWorking": true,
                   //             "time": 1662448836000,
                   //             "updateTime": 1662448836000
                   //         }
                   //     ]
                   //
                   return this->parseOrders(response, market, since, limit);
                 } else {
                   if (isTrue(isEqual(limit, ccxt::any{}))) {
                     ::setValue(request, std::string("page_size"), 100); // max
                   }
                   ccxt::any swapResponse =
                       awaitValue(this->contractPrivateGetOrderListOpenOrders(
                           this->extend(request, params)));
                   ccxt::any data = this->safeList(
                       swapResponse, std::string("data"), ccxt::list{});
                   return this->parseOrders(data, market, since, limit, params);
                 }
                 return ccxt::any{};
               })
        .share();
  }

