  virtual std::shared_future<ccxt::any>
  fetchOrdersByState(ccxt::any state, ccxt::any symbol = ccxt::any{},
                     ccxt::any since = ccxt::any{},
                     ccxt::any limit = ccxt::any{},
                     ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketTypeVariable = this->handleMarketTypeAndParams(
                     std::string("fetchOrdersByState"), market, params);
                 ccxt::any marketType = ::getValue(marketTypeVariable, 0);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   throw NotSupported(toString(add(
                       add(this->id,
                           std::string(
                               " fetchOrdersByState() is not supported for ")),
                       marketType)));
                 } else {
                   ::setValue(request, std::string("states"), state);
                   return awaitValue(this->fetchOrders(
                       symbol, since, limit, this->extend(request, params)));
                 }
                 return ccxt::any{};
               })
        .share();
  }

  /**
   * @method
   * @name mexc#cancelOrder
   * @description cancels an open order
   * @see https://www.mexc.com/api-docs/spot-v3/spot-account-trade/cancel-order
   * // spot
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/cancel-orders
   * // swap
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/cancel-planned-orders
   * // swap trigger
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.marginMode] only 'isolated' is supported for
   * spot-margin trading
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any request = ccxt::dict{};
                ccxt::any market = ccxt::any{};
                if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                  market = this->market(symbol);
                  ::setValue(request, std::string("symbol"),
                             ::getValue(market, std::string("id")));
                }
                ccxt::any marketType = ccxt::any{};
                ccxt::any marketTypeparamsVariable =
                    this->handleMarketTypeAndParams(std::string("cancelOrder"),
                                                    market, params);
                marketType = ::getValue(marketTypeparamsVariable, 0);
                params = ::getValue(marketTypeparamsVariable, 1);
                ccxt::any marginModequeryVariable =
                    this->handleMarginModeAndParams(std::string("cancelOrder"),
                                                    params);
                ccxt::any marginMode = ::getValue(marginModequeryVariable, 0);
                ccxt::any query = ::getValue(marginModequeryVariable, 1);
                ccxt::any data = ccxt::any{};
                if (isTrue(isEqual(marketType, std::string("spot")))) {
                  if (isTrue(isEqual(symbol, ccxt::any{}))) {
                    throw ArgumentsRequired(toString(
                        add(this->id,
                            std::string(
                                " cancelOrder() requires a symbol argument"))));
                  }
                  ccxt::any requestInner = ccxt::dict{
                      {std::string("symbol"),
                       this->safeString(market, std::string("id"))},
                  };
                  ccxt::any clientOrderId =
                      this->safeString(params, std::string("clientOrderId"));
                  if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                    params = this->omit(query, std::string("clientOrderId"));
                    ::setValue(requestInner, std::string("origClientOrderId"),
                               clientOrderId);
                  } else {
                    ::setValue(requestInner, std::string("orderId"), id);
                  }
                  if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
                    if (isTrue(!isEqual(marginMode, std::string("isolated")))) {
                      throw BadRequest(toString(
                          add(add(add(this->id,
                                      std::string(" cancelOrder() does not "
                                                  "support marginMode ")),
                                  marginMode),
                              std::string(" for spot-margin trading"))));
                    }
                    data = awaitValue(this->spotPrivateDeleteMarginOrder(
                        this->extend(requestInner, query)));
                  } else {
                    data = awaitValue(this->spotPrivateDeleteOrder(
                        this->extend(requestInner, query)));
                  }
                } else {
                  // TODO: PlanorderCancel endpoint has bug atm. waiting for
                  // fix.
                  ccxt::any
                      method =
                          this
                              ->safeString(
                                  this->options, std::string("cancelOrder"),
                                  std::string("contractPrivatePostOrderCance"
                                              "l")); // contractPrivatePostOrderCancel,
                                                     // contractPrivatePostPlanorderCancel
                  method =
                      this->safeString(query, std::string("method"), method);
                  ccxt::any response = ccxt::any{};
                  if (isTrue(isEqual(
                          method,
                          std::string("contractPrivatePostOrderCancel")))) {
                    response = awaitValue(
                        this->contractPrivatePostOrderCancel(ccxt::list{
                            id})); // the request cannot be changed or extended.
                                   // This is the only way to send.
                  } else if (isTrue(isEqual(
                                 method,
                                 std::string(
                                     "contractPrivatePostPlanorderCancel")))) {
                    response = awaitValue(
                        this->contractPrivatePostPlanorderCancel(ccxt::list{
                            id})); // the request cannot be changed or extended.
                                   // This is the only way to send.
                  } else {
                    throw NotSupported(toString(
                        add(this->id,
                            std::string(
                                " cancelOrder() not support this method"))));
                  }
                  //
                  //     {
                  //         "success": true,
                  //         "code": "0",
                  //         "data": [
                  //             {
                  //                 "orderId": "264995729269765120",
                  //                 "errorCode": "0",         // if already
                  //                 canceled: "2041"; if doesn't exist: "2040"
                  //                 "errorMsg": "success",    // if already
                  //                 canceled: "order state cannot be
                  //                 cancelled"; if doesn't exist: "order not
                  //                 exist"
                  //             }
                  //         ]
                  //     }
                  //
                  data = this->safeValue(response, std::string("data"));
                  ccxt::any order = this->safeValue(data, 0);
                  ccxt::any errorMsg = this->safeValue(
                      order, std::string("errorMsg"), std::string(""));
                  if (isTrue(!isEqual(errorMsg, std::string("success")))) {
                    throw InvalidOrder(toString(add(
                        add(add(add(this->id,
                                    std::string(
                                        " cancelOrder() the order with id ")),
                                id),
                            std::string(" cannot be cancelled: ")),
                        errorMsg)));
                  }
                }
                return this->parseOrder(data, market);
              })
            .share();
  }

  /**
   * @method
   * @name mexc#cancelOrders
   * @description cancel multiple orders
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/cancel-orders
   * @param {string[]} ids order ids
   * @param {string} symbol unified market symbol, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrders(ccxt::any ids, ccxt::any symbol = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = (isTrue((!isEqual(symbol, ccxt::any{})))
                                         ? ccxt::any(this->market(symbol))
                                         : ccxt::any(ccxt::any{}));
                 ccxt::any marketTypeVariable = this->handleMarketTypeAndParams(
                     std::string("cancelOrders"), market, params);
                 ccxt::any marketType = ::getValue(marketTypeVariable, 0);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   throw BadRequest(toString(
                       add(add(this->id,
                               std::string(
                                   " cancelOrders() is not supported for ")),
                           marketType)));
                 } else {
                   ccxt::any response =
                       awaitValue(this->contractPrivatePostOrderCancel(
                           ids)); // the request cannot be changed or extended.
                                  // The only way to send.
                   //
                   //     {
                   //         "success": true,
                   //         "code": "0",
                   //         "data": [
                   //             {
                   //                 "orderId": "264995729269765120",
                   //                 "errorCode": "0",         // if already
                   //                 canceled: "2041" "errorMsg": "success", //
                   //                 if already canceled: "order state cannot
                   //                 be cancelled"
                   //             },
                   //         ]
                   //     }
                   //
                   ccxt::any data =
                       this->safeList(response, std::string("data"));
                   return this->parseOrders(data, market);
                 }
                 return ccxt::any{};
               })
        .share();
  }

  /**
   * @method
   * @name mexc#cancelAllOrders
   * @description cancel all open orders
   * @see
   * https://www.mexc.com/api-docs/spot-v3/spot-account-trade/cancel-all-open-orders-on-a-symbol
   * // spot
   * @see
   * https://www.mexc.com/api-docs/spot-v3/spot-account-trade/cancel-all-orders
   * // spot all symbols
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/cancel-all-orders-under-a-contract
   * // swap
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/cancel-all-planned-orders
   * // swap trigger
   * @param {string} [symbol] unified market symbol, only orders in the market
   * of this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("cancelAllOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   if (isTrue(isEqual(symbol, ccxt::any{}))) {
                     awaitValue(this->spotPrivateDeleteOrderAll(params));
                     //
                     //     {
                     //         "code": 200,
                     //         "msg": "success",
                     //         "timestamp": 1778744778528
                     //     }
                     //
                     return ccxt::list{};
                   }
                   ::setValue(request, std::string("symbol"),
                              this->safeString(market, std::string("id")));
                   ccxt::any response =
                       awaitValue(this->spotPrivateDeleteOpenOrders(
                           this->extend(request, params)));
                   //
                   // spot
                   //
                   //     [
                   //         {
                   //             "symbol": "BTCUSDT",
                   //             "orderId": "133926492139692032",
                   //             "price": "30000",
                   //             "origQty": "0.0002",
                   //             "type": "LIMIT",
                   //             "side": "BUY"
                   //         },
                   //     ]
                   //
                   return this->parseOrders(response, market);
                 } else {
                   if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                     ::setValue(request, std::string("symbol"),
                                this->safeString(market, std::string("id")));
                   }
                   // method can be either: contractPrivatePostOrderCancelAll or
                   // contractPrivatePostPlanorderCancelAll the Planorder
                   // endpoints work not only for stop-market orders but also
                   // for stop-limit orders that are supposed to have separate
                   // endpoint
                   ccxt::any method = this->safeString(
                       this->options, std::string("cancelAllOrders"),
                       std::string("contractPrivatePostOrderCancelAll"));
                   method =
                       this->safeString(params, std::string("method"), method);
                   ccxt::any response = ccxt::dict{};
                   if (isTrue(isEqual(
                           method,
                           std::string("contractPrivatePostOrderCancelAll")))) {
                     response =
                         awaitValue(this->contractPrivatePostOrderCancelAll(
                             this->extend(request, params)));
                   } else if (isTrue(isEqual(
                                  method, std::string("contractPrivatePostPlano"
                                                      "rderCancelAll")))) {
                     response =
                         awaitValue(this->contractPrivatePostPlanorderCancelAll(
                             this->extend(request, params)));
                   }
                   //
                   //     {
                   //         "success": true,
                   //         "code": "0"
                   //     }
                   //
                   ccxt::any data = this->safeList(
                       response, std::string("data"), ccxt::list{});
                   return this->parseOrders(data, market);
                 }
                 return ccxt::any{};
               })
        .share();
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // spot
    //    createOrder
    //
    //    {
    //        "symbol": "FARTCOINUSDT",
    //        "orderId": "C02__342252993005723644225",
    //        "orderListId": "-1",
    //        "price": "1.1",
    //        "origQty": "6.3",
    //        "type": "IMMEDIATE_OR_CANCEL",
    //        "side": "SELL",
    //        "transactTime": "1745852205223"
    //    }
    //
    //    unknown endpoint on spot
    //
    //    {
    //         "symbol": "BTCUSDT",
    //         "orderId": "123738410679123456",
    //         "orderListId": -1
    //    }
    //
    // margin: createOrder
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "orderId": "762634301354414080",
    //         "clientOrderId": null,
    //         "isIsolated": true,
    //         "transactTime": 1661992652132
    //     }
    //
    // spot: cancelOrder, cancelAllOrders
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "orderId": "133926441921286144",
    //         "price": "30000",
    //         "origQty": "0.0002",
    //         "type": "LIMIT",
    //         "side": "BUY"
    //     }
    //
    // margin: cancelOrder, cancelAllOrders
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "orderId": "762640232574226432",
    //         "orderListId": "-1",
    //         "clientOrderId": null,
    //         "price": "18000",
    //         "origQty": "0.00147",
    //         "executedQty": "0",
    //         "cummulativeQuoteQty": "0",
    //         "status": "NEW",
    //         "type": "LIMIT",
    //         "side": "BUY",
    //         "isIsolated": true,
    //         "isWorking": true,
    //         "time": 1661994066000,
    //         "updateTime": 1661994066000
    //     }
    //
    // spot: fetchOrder, fetchOpenOrders, fetchOrders
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "orderId": "133734823834147272",
    //         "orderListId": "-1",
    //         "clientOrderId": null,
    //         "price": "30000",
    //         "origQty": "0.0002",
    //         "executedQty": "0",
    //         "cummulativeQuoteQty": "0",
    //         "status": "CANCELED",
    //         "timeInForce": null,
    //         "type": "LIMIT",
    //         "side": "BUY",
    //         "stopPrice": null,
    //         "icebergQty": null,
    //         "time": "1647667102000",
    //         "updateTime": "1647708567000",
    //         "isWorking": true,
    //         "origQuoteOrderQty": "6"
    //     }
    //
    // margin: fetchOrder, fetchOrders
    //
    //     {
    //         "symbol": "BTCUSDT",
    //         "orderId": "763307297891028992",
    //         "orderListId": "-1",
    //         "clientOrderId": null,
    //         "price": "18000",
    //         "origQty": "0.0014",
    //         "executedQty": "0",
    //         "cummulativeQuoteQty": "0",
    //         "status": "NEW",
    //         "type": "LIMIT",
    //         "side": "BUY",
    //         "isIsolated": true,
    //         "isWorking": true,
    //         "time": 1662153107000,
    //         "updateTime": 1662153107000
    //     }
    //
    // swap: createOrder
    //
    //     2ff3163e8617443cb9c6fc19d42b1ca4
    //
    // swap: fetchOrder, fetchOrders
    //
    //     regular
    //     {
    //         "orderId": "264995729269765120",
    //         "symbol": "STEPN_USDT",
    //         "positionId": "0",
    //         "price": "2.2",
    //         "vol": "15",
    //         "leverage": "20",
    //         "side": "1", // TODO: not unified
    //         "category": "1",
    //         "orderType": "1", // TODO: not unified
    //         "dealAvgPrice": "0",
    //         "dealVol": "0",
    //         "orderMargin": "2.2528",
    //         "takerFee": "0",
    //         "makerFee": "0",
    //         "profit": "0",
    //         "feeCurrency": "USDT",
    //         "openType": "1",
    //         "state": "2", // TODO
    //         "externalOid": "_m_0e9520c256744d64b942985189026d20",
    //         "errorCode": "0",
    //         "usedMargin": "0",
    //         "createTime": "1648850305236",
    //         "updateTime": "1648850305245",
    //         "positionMode": "1"
    //     }
    //
    //     stop
    //     {
    //         "id": "265557643326564352",
    //         "triggerType": "1",
    //         "triggerPrice": "3",
    //         "price": "2.9", // not present in stop-market, but in stop-limit
    //         order "executeCycle": "87600", "trend": "1",
    //          // below keys are same as in regular order structure
    //         "symbol": "STEPN_USDT",
    //         "leverage": "20",
    //         "side": "1",
    //         "vol": "13",
    //         "openType": "1",
    //         "state": "1",
    //         "orderType": "1",
    //         "errorCode": "0",
    //         "createTime": "1648984276000",
    //         "updateTime": "1648984276000",
    //     }
    //
    // createOrders error
    //
    //     {
    //         "newClientOrderId": "123456",
    //         "msg": "The minimum transaction volume cannot be less
    //         than:0.5USDT", "code": 30002
    //     }
    //
    ccxt::any code = this->safeInteger(order, std::string("code"));
    if (isTrue(!isEqual(code, ccxt::any{}))) {
      // error upon placing multiple orders
      return this->safeOrder(ccxt::dict{
          {std::string("info"), order},
          {std::string("status"), std::string("rejected")},
          {std::string("clientOrderId"),
           this->safeString(order, std::string("newClientOrderId"))},
      });
    }
    ccxt::any id = ccxt::any{};
    if (isTrue(isString(order))) {
      id = order;
    } else {
      id = this->safeString2(order, std::string("orderId"), std::string("id"));
    }
    ccxt::any timeInForce = this->parseOrderTimeInForce(
        this->safeString(order, std::string("timeInForce")));
    ccxt::any typeRaw = this->safeString(order, std::string("type"));
    if (isTrue(isEqual(timeInForce, ccxt::any{}))) {
      timeInForce = this->getTifFromRawOrderType(typeRaw);
    }
    ccxt::any marketId = this->safeString(order, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    ccxt::any timestamp = this->safeIntegerN(
        order, ccxt::list{std::string("time"), std::string("createTime"),
                          std::string("transactTime")});
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCurrency = this->safeString(order, std::string("feeCurrency"));
    if (isTrue(!isEqual(feeCurrency, ccxt::any{}))) {
      ccxt::any takerFee = this->safeString(order, std::string("takerFee"));
      ccxt::any makerFee = this->safeString(order, std::string("makerFee"));
      ccxt::any feeSum = ccxt::Precise::stringAdd(takerFee, makerFee);
      fee = ccxt::dict{
          {std::string("currency"), feeCurrency},
          {std::string("cost"), this->parseNumber(feeSum)},
      };
    }
    return this->safeOrder(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("clientOrderId"),
             this->safeString(order, std::string("clientOrderId"))},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"), ccxt::any{}},
            {std::string("lastUpdateTimestamp"),
             this->safeInteger(order, std::string("updateTime"))},
            {std::string("status"),
             this->parseOrderStatus(this->safeString2(
                 order, std::string("status"), std::string("state")))},
            {std::string("symbol"), ::getValue(market, std::string("symbol"))},
            {std::string("type"), this->parseOrderType(typeRaw)},
            {std::string("timeInForce"), timeInForce},
            {std::string("side"), this->parseOrderSide(this->safeString(
                                      order, std::string("side")))},
            {std::string("price"),
             this->safeNumber(order, std::string("price"))},
            {std::string("triggerPrice"),
             this->safeNumber2(order, std::string("stopPrice"),
                               std::string("triggerPrice"))},
            {std::string("average"),
             this->safeNumber(order, std::string("dealAvgPrice"))},
            {std::string("amount"),
             this->safeNumber2(order, std::string("origQty"),
                               std::string("vol"))},
            {std::string("cost"),
             this->safeNumber(order, std::string("cummulativeQuoteQty"))},
            {std::string("filled"),
             this->safeNumber2(order, std::string("executedQty"),
                               std::string("dealVol"))},
            {std::string("remaining"), ccxt::any{}},
            {std::string("fee"), fee},
            {std::string("trades"), ccxt::any{}},
            {std::string("info"), order},
        },
        market);
  }

  virtual ccxt::any parseOrderSide(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("BUY"), std::string("buy")},
        {std::string("SELL"), std::string("sell")},
        {std::string("1"), std::string("buy")},
        {std::string("2"), std::string("sell")},
    };
    return this->safeString(statuses, status, status);
  }

