  /**
   * @method
   * @name mexc#fetchPosition
   * @description fetch data on a single open contract trade position
   * @see
   * https://www.mexc.com/api-docs/futures/account-and-trading-endpoints/get-open-positions
   * @param {string} symbol unified market symbol of the market the position is
   * held in, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPosition(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = this->market(symbol);
                        ccxt::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        ccxt::any response = awaitValue(this->fetchPositions(
                            ccxt::any{}, this->extend(request, params)));
                        return this->safeValue(response, 0);
                      })
        .share();
  }

